const KHATMA_PLANS={"ashr-10":{name:"ختمة العشر",days:10,juzPerDay:3,desc:"3 أجزاء يومياً — تختم في العشر"},monthly:{name:"ختمة شهرية",days:30,juzPerDay:1,desc:"جزء واحد يومياً"},"two-month":{name:"ختمة الشهرين",days:60,juzPerDay:.5,desc:"نصف جزء يومياً — للمبتدئين"},weekly:{name:"ختمة أسبوعية",days:7,juzPerDay:4.3,desc:"للحُفّاظ — ختمة كل أسبوع"}};function getActiveKhatmaPlan(){return localStorage.getItem("zad_khatma_plan")||"ashr-10"}function setKhatmaPlan(planId){localStorage.setItem("zad_khatma_plan",planId);renderKhatmaPlans();if(typeof showToast==="function")showToast(`✅ ${KHATMA_PLANS[planId].name}`)}window.setKhatmaPlan=setKhatmaPlan;function renderKhatmaPlans(){const container=document.getElementById("khatma-plans");if(!container)return;const active=getActiveKhatmaPlan();container.innerHTML=Object.entries(KHATMA_PLANS).map(([id,plan])=>`\n    <div class="khatma-plan-card ${id===active?"active":""}" onclick="setKhatmaPlan('${id}')">\n      <div class="kp-name">${plan.name}</div>\n      <div class="kp-desc">${plan.desc}</div>\n      <div class="kp-days">${plan.days} يوم</div>\n    </div>\n  `).join("")}const SURAHS_SHORT=[{n:114,name:"الناس",ayat:6},{n:113,name:"الفلق",ayat:5},{n:112,name:"الإخلاص",ayat:4},{n:111,name:"المسد",ayat:5},{n:110,name:"النصر",ayat:3},{n:109,name:"الكافرون",ayat:6},{n:108,name:"الكوثر",ayat:3},{n:107,name:"الماعون",ayat:7},{n:106,name:"قريش",ayat:4},{n:105,name:"الفيل",ayat:5}];async function getHifzProgress(){try{return await(window.ZadStore?.getState("hifzProgress",{}))||{}}catch{return{}}}async function toggleHifz(surahNum){const progress=await getHifzProgress();if(progress[surahNum]){delete progress[surahNum]}else{progress[surahNum]={masteredAt:Date.now(),reviewCount:0}}await(window.ZadStore?.setState("hifzProgress",progress));renderHifzTracker()}window.toggleHifz=toggleHifz;async function renderHifzTracker(){const container=document.getElementById("hifz-tracker");if(!container)return;const progress=await getHifzProgress();const memorized=Object.keys(progress).length;container.innerHTML=`\n    <div class="hifz-stats">\n      <div class="hifz-stat-num">${memorized}</div>\n      <div class="hifz-stat-lbl">سورة محفوظة من ${SURAHS_SHORT.length} (جزء عمّ)</div>\n    </div>\n    <div class="hifz-grid">\n      ${SURAHS_SHORT.map(s=>`\n        <div class="hifz-surah ${progress[s.n]?"memorized":""}" onclick="toggleHifz(${s.n})">\n          <span class="hifz-surah-name">${s.name}</span>\n          <span class="hifz-surah-ayat">${s.ayat} آيات</span>\n          ${progress[s.n]?'<span class="hifz-check">✓</span>':""}\n        </div>\n      `).join("")}\n    </div>`}const QURAN_APIS={primary:{name:"Quran.com API",base:"https://api.quran.com/api/v4",features:["نص عثماني","تفسير (ابن كثير، السعدي، الطبري)","تلاوة","ترجمة 40+ لغة"],needsKey:false},fallback:{name:"AlQuran.cloud",base:"https://api.alquran.cloud/v1",features:["نص","تلاوة","بسيط بدون مفتاح"],needsKey:false}};async function fetchVerse(surah,ayah){try{const url=`${QURAN_APIS.primary.base}/verses/by_key/${surah}:${ayah}?fields=text_uthmani&translations=131`;const res=await fetch(url);if(res.ok){const data=await res.json();return{text:data.verse?.text_uthmani,translation:data.verse?.translations?.[0]?.text,source:"Quran.com"}}throw new Error("primary failed")}catch{try{const url=`${QURAN_APIS.fallback.base}/ayah/${surah}:${ayah}/quran-uthmani`;const res=await fetch(url);const data=await res.json();return{text:data.data?.text,translation:null,source:"AlQuran.cloud"}}catch{return null}}}window.fetchVerse=fetchVerse;const QURAN_CSS=`\n#khatma-plans { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }\n.khatma-plan-card { padding: 16px; border-radius: 14px; border: 2px solid var(--border, #ddd);\n  background: var(--sand, #faf9f6); cursor: pointer; transition: all .2s; text-align: center; }\n.khatma-plan-card.active { border-color: var(--zad-green-900, #0e3b2e); background: rgba(14,59,46,.06); }\n.kp-name { font-weight: 800; font-size: 15px; margin-bottom: 4px; }\n.kp-desc { font-size: 12px; color: var(--muted, #888); margin-bottom: 8px; line-height: 1.5; }\n.kp-days { font-size: 13px; font-weight: 700; color: var(--green-mid, #1a5d47); }\n.hifz-stats { text-align: center; margin-bottom: 20px; }\n.hifz-stat-num { font-size: 42px; font-weight: 900; color: var(--green-deep, #0e3b2e); }\n.hifz-stat-lbl { font-size: 13px; color: var(--muted, #888); }\n.hifz-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); gap: 8px; }\n.hifz-surah { position: relative; padding: 12px 8px; border-radius: 10px; border: 1.5px solid var(--border, #ddd);\n  background: var(--sand, #faf9f6); cursor: pointer; text-align: center; transition: all .2s; }\n.hifz-surah.memorized { background: rgba(14,59,46,.1); border-color: var(--zad-green-700, #1a5d47); }\n.hifz-surah-name { display: block; font-weight: 700; font-size: 14px; }\n.hifz-surah-ayat { display: block; font-size: 11px; color: var(--muted, #888); margin-top: 2px; }\n.hifz-check { position: absolute; top: 4px; left: 4px; color: var(--green-mid, #1a5d47); font-weight: 900; }\n`;function injectQuranCSS(){if(document.getElementById("quran-module-css"))return;const s=document.createElement("style");s.id="quran-module-css";s.textContent=QURAN_CSS;document.head.appendChild(s)}document.addEventListener("DOMContentLoaded",()=>{const hasModule=document.getElementById("khatma-plans")||document.getElementById("hifz-tracker");if(hasModule){injectQuranCSS();renderKhatmaPlans();renderHifzTracker();console.log("[QuranModule] ✅ موديول القرآن جاهز")}});window.KHATMA_PLANS=KHATMA_PLANS;window.QURAN_APIS=QURAN_APIS;